local M = {}
local DB = require "lib.database"
local VehicleParser = require "lib.ExtendetParser"
local Generator = require "lib.Generator"
M.info = "Система статистики и достижений"
M.ver = "0.9 Beta"

local Achivment = {}
extended(Achivment, DB)
function Achivment:init(path)
    local db_instance = DB:init(path) -- Инициализация DB
    -- Копируем поля из db_instance в self
    for key, value in pairs(db_instance) do
        self[key] = value
    end
    self.listAchiment = load_config("settings/achivment")
    return self
end

function Achivment:SendUi(user, achivment_name)
    local achi = self.listAchiment[achivment_name]
    local data = {}
    if achi == nil then
        return
    end
    data.title = achi.title
    if achi.desc ~= nil then
        data.desc = achi.desc
    end
    if achi.image ~= nil then
        data.image = achi.image
    end
    if achi.audio ~= nil then
        data.audio = achi.audio
    end
    data.name = achivment_name
    log("Отправляем пользователю "..user.." достижение "..achivment_name,2)
    MP.TriggerClientEventJson(MP.GetId(user),"AchievementUIRun",data)
end


---@param user string
function Achivment:compare(user)
    if self.database[user] == nil then
        return
    end
    if self.database[user]["achivments"] == nil then
        self.database[user]["achivments"] = {}
    end
    for achivment_name,data in pairs(self.listAchiment) do
        local req = data.req
        --print(achivment_name,data)
        if self.database[user]["achivments"][achivment_name] == nil then
            if self.database[user][req.key] ~= nil and self.database[user][req.key]['value'] >= req.value then
                log("Пользователь "..user.." получил достижение "..achivment_name,2)
                self:SendUi(user,achivment_name)

            end
        end
    end
end


---@param user string
---@param key string name_achivment
---@param value number value
function Achivment:addInfo(user,key,value)
    self.database = self.database or {}
    self.database[user] = self.database[user] or {}

    if self.database[user][key] == nil then
        self.database[user][key] = {}
        self.database[user][key]['value'] = value
    else
        self.database[user][key]['value'] = self.database[user][key]['value'] + value
    end
    self:unstable_save()
    self:compare(user)
    return self.database[user][key]
end

function Achivment:setInfo(user,key,value)
    local old_value = self.database[user][key]['value']
    self.database[user] = self.database[user] or {}
    self.database[user][key] = {}
    self.database[user][key]['value'] = value
    if old_value == value then
        return
    end
    self:unstable_save()
    self:compare(user)
    return self.database[user][key]
end


function AchivmentAccept(id,data)
    local user = MP.GetPlayerName(id)
    log("Пользователь "..user.." принял достижение "..data,2)
    data = Util.JsonDecode(data)
    if data == nil then
        return
    end
    if data and data.name then
        if statistic.database[user]["achivments"][data.name] == nil then
            statistic.database[user]["achivments"][data.name] = timer:get()
            statistic:save()
        end
    end
end

local function CheckAchivment(name)
    statistic:compare(name)
end

function AchivmentReload(id,data)
    HeventTimer.Createtask(5,CheckAchivment,"CheckAchivment"..id,MP.GetPlayerName(id))
end

-- Функции вызываемые при тригере
statistic = Achivment:init("StatisticsForAchivment.ixt")

